function validate([row]) {
  if (row.length % 2 !== 0 || row.length < 4 || row.length > 60) return 'row needs an even length from 4 to 60.';
  const seen = new Set();
  for (const id of row) {
    if (!Number.isInteger(id) || id < 0 || id >= row.length) return 'Each ID is between 0 and row.length - 1.';
    if (seen.has(id)) return 'Every ID must appear only once.';
    seen.add(id);
  }
  return null;
}

