function minSwapsCouples(row) {
  const seated = r => {
    for (let i = 0; i < r.length; i += 2) if (Math.floor(r[i] / 2) !== Math.floor(r[i + 1] / 2)) return false;
    return true;
  };
  if (row.length <= 8) {
    // Breadth-first search over seatings: the first level holding a finished seating is the answer.
    let frontier = [row.slice()];
    const seen = new Set([row.join(',')]);
    for (let swaps = 0; ; swaps++) {
      const next = [];
      for (const current of frontier) {
        if (seated(current)) return swaps;
        for (let a = 0; a < current.length; a++) {
          for (let b = a + 1; b < current.length; b++) {
            const swapped = current.slice();
            [swapped[a], swapped[b]] = [swapped[b], swapped[a]];
            const key = swapped.join(',');
            if (!seen.has(key)) { seen.add(key); next.push(swapped); }
          }
        }
      }
      frontier = next;
    }
  }
  // Longer rows: join the two couples sharing each seat pair; a group of k couples needs k - 1 swaps.
  const parent = Array.from({ length: row.length / 2 }, (_, i) => i);
  const find = x => (parent[x] === x ? x : (parent[x] = find(parent[x])));
  let groups = row.length / 2;
  for (let i = 0; i < row.length; i += 2) {
    const a = find(Math.floor(row[i] / 2)), b = find(Math.floor(row[i + 1] / 2));
    if (a !== b) { parent[a] = b; groups--; }
  }
  return row.length / 2 - groups;
}

