function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 26 + pick(5) : 2 + pick(3);
  const row = Array.from({ length: 2 * n }, (_, i) => i);
  const swap = (a, b) => { [row[a], row[b]] = [row[b], row[a]]; };
  const mode = pick(3);
  if (mode === 0) {
    for (let i = row.length - 1; i > 0; i--) swap(i, pick(i + 1));
  } else if (mode === 1) {
    // Seated couples disturbed by a few random swaps.
    for (let t = pick(size === 'large' ? 12 : 4); t > 0; t--) swap(pick(row.length), pick(row.length));
  } else {
    // Shuffle whole couples and the order inside each couple, then rotate one stretch of seats.
    const couples = Array.from({ length: n }, (_, k) => (rand() < 0.5 ? [2 * k, 2 * k + 1] : [2 * k + 1, 2 * k]));
    for (let i = couples.length - 1; i > 0; i--) { const j = pick(i + 1); [couples[i], couples[j]] = [couples[j], couples[i]]; }
    row.splice(0, row.length, ...couples.flat());
    const from = pick(row.length), to = from + pick(row.length - from);
    row.splice(from, to - from + 1, ...row.slice(from + 1, to + 1), row[from]);
  }
  return [row];
}
